[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GreenBean Coffee — Your Daily Coffee Ritual</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@700;800&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #00824A;
      --green-dark: #006B3C;
      --forest: #32462F;
      --cream: #F3CEA1;
      --cream-light: #FDF6EC;
      --cream-mid: #F9EDD8;
      --brown: #5C3D2E;
      --text: #1A1A1A;
      --text-mid: #444;
      --text-light: #777;
      --white: #FFFFFF;
      --radius: 16px;
      --shadow: 0 4px 24px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 48px rgba(0,0,0,0.14);
    }

    body {
      font-family: 'DM Sans', sans-serif;
      background: var(--white);
      color: var(--text);
      line-height: 1.6;
    }

    /* HEADER */
    header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: var(--white);
      border-bottom: 1px solid rgba(0,130,74,0.12);
      box-shadow: 0 2px 16px rgba(0,0,0,0.06);
    }
    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
    }
    .logo-mark {
      width: 44px;
      height: 44px;
      background: var(--green);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .logo-mark svg { width: 26px; height: 26px; }
    .logo-text {
      font-family: 'Playfair Display', serif;
      font-size: 22px;
      font-weight: 700;
      color: var(--forest);
      letter-spacing: -0.3px;
    }
    nav { display: flex; align-items: center; gap: 8px; }
    nav a {
      text-decoration: none;
      color: var(--text);
      font-size: 15px;
      font-weight: 500;
      padding: 8px 14px;
      border-radius: 999px;
      transition: background 0.2s, color 0.2s;
    }
    nav a:hover { background: var(--cream-light); color: var(--green); }
    nav a.active { color: var(--green); font-weight: 600; }
    .header-actions { display: flex; align-items: center; gap: 10px; }
    .btn-ghost {
      background: none;
      border: 2px solid var(--green);
      color: var(--green);
      padding: 8px 20px;
      border-radius: 999px;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: background 0.2s, color 0.2s;
    }
    .btn-ghost:hover { background: var(--green); color: var(--white); }
    .btn-solid {
      background: var(--green);
      border: 2px solid var(--green);
      color: var(--white);
      padding: 8px 20px;
      border-radius: 999px;
      font-size: 14px;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: background 0.2s, border-color 0.2s, transform 0.15s;
    }
    .btn-solid:hover { background: var(--green-dark); border-color: var(--green-dark); transform: translateY(-1px); }

    /* HERO */
    .hero {
      background: linear-gradient(135deg, var(--forest) 0%, #1a2e18 60%, #2d4a2a 100%);
      min-height: 520px;
      display: flex;
      align-items: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 70% 50%, rgba(243,206,161,0.15) 0%, transparent 70%);
    }
    .hero-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 80px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
      width: 100%;
      position: relative;
    }
    .hero-content { color: var(--white); }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(243,206,161,0.2);
      border: 1px solid rgba(243,206,161,0.4);
      color: var(--cream);
      font-size: 13px;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 999px;
      margin-bottom: 24px;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }
    .hero h1 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(40px, 5vw, 64px);
      font-weight: 800;
      line-height: 1.1;
      color: var(--white);
      margin-bottom: 20px;
      letter-spacing: -1px;
    }
    .hero p {
      font-size: 18px;
      color: rgba(255,255,255,0.75);
      margin-bottom: 36px;
      max-width: 420px;
      line-height: 1.7;
    }
    .hero-cta { display: flex; gap: 14px; flex-wrap: wrap; }
    .btn-cream {
      background: var(--cream);
      color: var(--forest);
      padding: 14px 32px;
      border-radius: 999px;
      font-size: 16px;
      font-weight: 700;
      text-decoration: none;
      border: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
    }
    .btn-cream:hover { background: #f0c48a; transform: translateY(-2px); }
    .btn-outline-white {
      background: transparent;
      color: var(--white);
      padding: 14px 32px;
      border-radius: 999px;
      font-size: 16px;
      font-weight: 600;
      text-decoration: none;
      border: 2px solid rgba(255,255,255,0.4);
      cursor: pointer;
      transition: background 0.2s, border-color 0.2s;
    }
    .btn-outline-white:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.7); }
    .hero-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    .hero-img-placeholder {
      width: 100%;
      max-width: 420px;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, rgba(243,206,161,0.25) 0%, rgba(0,130,74,0.3) 100%);
      border-radius: 24px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      border: 1px solid rgba(255,255,255,0.1);
      position: relative;
      overflow: hidden;
    }
    .hero-img-placeholder::before {
      content: '';
      position: absolute;
      bottom: -30px;
      right: -30px;
      width: 200px;
      height: 200px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(243,206,161,0.2) 0%, transparent 70%);
    }
    .coffee-icon { font-size: 72px; }
    .hero-img-placeholder p { color: rgba(255,255,255,0.5); font-size: 13px; }

    /* PROMO CARDS */
    .section { padding: 72px 24px; }
    .section-inner { max-width: 1280px; margin: 0 auto; }

    .promo-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
      gap: 24px;
    }

    .promo-card {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow);
      display: flex;
      flex-direction: column;
      transition: transform 0.25s, box-shadow 0.25s;
    }
    .promo-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
    .promo-card-img {
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 48px;
      position: relative;
      overflow: hidden;
    }
    .promo-card-img::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to bottom, transparent 50%, rgba(0,0,0,0.2) 100%);
    }
    .promo-card-body {
      padding: 28px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }
    .promo-card-body h3 {
      font-family: 'Playfair Display', serif;
      font-size: 22px;
      font-weight: 700;
      color: var(--forest);
      margin-bottom: 10px;
      line-height: 1.3;
    }
    .promo-card-body p {
      font-size: 15px;
      color: var(--text-mid);
      line-height: 1.7;
      margin-bottom: 20px;
      flex: 1;
    }
    .btn-green {
      display: inline-block;
      background: var(--green);
      color: var(--white);
      padding: 10px 24px;
      border-radius: 999px;
      font-size: 14px;
      font-weight: 600;
      text-decoration: none;
      border: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.15s;
      align-self: flex-start;
    }
    .btn-green:hover { background: var(--green-dark); transform: translateY(-1px); }

    /* FEATURED PRODUCT */
    .featured-product {
      background: var(--cream-light);
    }
    .featured-product-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .featured-text .label {
      display: inline-block;
      background: var(--green);
      color: var(--white);
      font-size: 12px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      padding: 4px 12px;
      border-radius: 999px;
      margin-bottom: 16px;
    }
    .featured-text h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 800;
      color: var(--forest);
      margin-bottom: 16px;
      line-height: 1.2;
    }
    .featured-text p {
      font-size: 16px;
      color: var(--text-mid);
      line-height: 1.8;
      margin-bottom: 28px;
    }
    .featured-visual {
      background: linear-gradient(135deg, #e8f5f0 0%, #c8e8da 100%);
      border-radius: 24px;
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 80px;
      box-shadow: var(--shadow);
    }

    /* AI RECOMMENDATION */
    .ai-section {
      background: linear-gradient(135deg, var(--forest) 0%, #1e3a1a 100%);
      padding: 72px 24px;
    }
    .ai-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
      color: var(--white);
    }
    .ai-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(243,206,161,0.15);
      border: 1px solid rgba(243,206,161,0.3);
      color: var(--cream);
      font-size: 13px;
      font-weight: 600;
      padding: 6px 16px;
      border-radius: 999px;
      margin-bottom: 24px;
    }
    .ai-inner h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(28px, 4vw, 44px);
      font-weight: 800;
      margin-bottom: 16px;
      color: var(--white);
    }
    .ai-inner p {
      font-size: 17px;
      color: rgba(255,255,255,0.72);
      line-height: 1.7;
      margin-bottom: 32px;
    }

    /* SEASONAL HIGHLIGHTS */
    .seasonal-section { background: var(--cream-mid); }
    .seasonal-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
    }
    .seasonal-card {
      background: var(--white);
      border-radius: 20px;
      overflow: hidden;
      box-shadow: var(--shadow);
      display: flex;
      flex-direction: column;
    }
    .seasonal-card-img {
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 56px;
    }
    .seasonal-card-body { padding: 28px; }
    .seasonal-card-body h3 {
      font-family: 'Playfair Display', serif;
      font-size: 22px;
      font-weight: 700;
      color: var(--forest);
      margin-bottom: 10px;
    }
    .seasonal-card-body p {
      font-size: 15px;
      color: var(--text-mid);
      line-height: 1.7;
      margin-bottom: 20px;
    }

    /* NONDAIRY PROMO */
    .nondairy-section {
      background: linear-gradient(135deg, #f0f9f4 0%, #e0f4ea 100%);
      padding: 72px 24px;
    }
    .nondairy-inner {
      max-width: 1100px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 48px;
      align-items: center;
    }
    .nondairy-icon { font-size: 96px; }
    .nondairy-text h2 {
      font-family: 'Playfair Display', serif;
      font-size: clamp(26px, 3vw, 40px);
      font-weight: 800;
      color: var(--forest);
      margin-bottom: 12px;
    }
    .nondairy-text p {
      font-size: 16px;
      color: var(--text-mid);
      line-height: 1.8;
      margin-bottom: 24px;
      max-width: 540px;
    }

    /* FOOTER */
    footer {
      background: var(--forest);
      color: rgba(255,255,255,0.85);
      padding: 64px 24px 32px;
    }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 48px;
      margin-bottom: 48px;
    }
    .footer-col h4 {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--cream);
      margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 10px; }
    .footer-col ul li a {
      text-decoration: none;
      color: rgba(255,255,255,0.65);
      font-size: 14px;
      transition: color 0.2s;
    }
    .footer-col ul li a:hover { color: var(--cream); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.12);
      padding-top: 28px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }
    .footer-logo {
      display: flex;
      align-items: center;
      gap: 10px;
    }
    .footer-logo-mark {
      width: 36px;
      height: 36px;
      background: var(--green);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .footer-logo-text {
      font-family: 'Playfair Display', serif;
      font-size: 18px;
      font-weight: 700;
      color: var(--cream);
    }
    .footer-copy {
      font-size: 13px;
      color: rgba(255,255,255,0.4);
    }

    /* COOKIE BANNER */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--white);
      border-top: 2px solid var(--cream);
      box-shadow: 0 -4px 32px rgba(0,0,0,0.12);
      z-index: 1000;
      padding: 20px 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      flex-wrap: wrap;
    }
    .cookie-text h4 {
      font-size: 16px;
      font-weight: 700;
      color: var(--forest);
      margin-bottom: 4px;
    }
    .cookie-text p {
      font-size: 14px;
      color: var(--text-mid);
      max-width: 600px;
    }
    .cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
    .cookie-banner.hidden { display: none; }

    /* MOBILE */
    @media (max-width: 900px) {
      .hero-inner { grid-template-columns: 1fr; }
      .hero-visual { display: none; }
      .featured-product-inner { grid-template-columns: 1fr; }
      .featured-visual { order: -1; }
      .seasonal-inner { grid-template-columns: 1fr; }
      .nondairy-inner { grid-template-columns: 1fr; text-align: center; }
      .nondairy-icon { margin: 0 auto; }
    }
    @media (max-width: 768px) {
      .header-inner { padding: 0 16px; }
      nav { display: none; }
      .section { padding: 48px 16px; }
      .hero-inner { padding: 56px 16px; }
      .footer-grid { grid-template-columns: 1fr; gap: 8px; }
      .footer-col { border-bottom: 1px solid rgba(255,255,255,0.1); }
      .footer-col-toggle { cursor: pointer; display: flex; align-items: center; justify-content: space-between; }
      .footer-col-links { display: none; }
      .footer-col.open .footer-col-links { display: block; }
      .footer-col.open .toggle-icon { transform: rotate(180deg); }
      .toggle-icon { transition: transform 0.2s; display: inline-block; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
      .promo-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 480px) {
      .hero h1 { font-size: 32px; }
      .featured-text h2 { font-size: 26px; }
      .ai-inner h2 { font-size: 26px; }
    }
  </style>
</head>
<body>

  <!-- HEADER -->
  <header>
    <div class="header-inner">
      <a href="index.html" class="logo">
        <div class="logo-mark">
          <svg viewBox="0 0 26 26" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M13 3C7.477 3 3 7.477 3 13s4.477 10 10 10 10-4.477 10-10S18.523 3 13 3z" fill="white" fill-opacity="0.25"/>
            <path d="M8 12c0-2.761 2.239-5 5-5s5 2.239 5 5v2H8v-2z" fill="white"/>
            <path d="M9 17h8l-1 3H10l-1-3z" fill="white" fill-opacity="0.8"/>
          </svg>
        </div>
        <span class="logo-text">GreenBean</span>
      </a>
      <nav>
        <a href="menu.html">Menu</a>
        <a href="rewards.html">Rewards</a>
        <a href="gift.html">Gift Cards</a>
        <a href="store-locator.html">Find a store</a>
      </nav>
      <div class="header-actions">
        <a href="#" class="btn-ghost">Sign in</a>
        <a href="#" class="btn-solid">Join now</a>
      </div>
    </div>
  </header>

  <!-- HERO -->
  <section class="hero">
    <div class="hero-inner">
      <div class="hero-content">
        <div class="hero-badge">
          <span>🌱</span> Spring Collection 2024
        </div>
        <h1>It's a great day for coffee</h1>
        <p>Handcrafted drinks made exactly the way you love. Order ahead, earn Stars, and sip something seasonal.</p>
        <div class="hero-cta">
          <a href="menu.html" class="btn-cream">Start an order</a>
          <a href="menu.html" class="btn-outline-white">View our menu</a>
        </div>
      </div>
      <div class="hero-visual">
        <div class="hero-img-placeholder">
          <div class="coffee-icon">☕</div>
          <p>Seasonal drink photography</p>
        </div>
      </div>
    </div>
  </section>

  <!-- FEATURED PRODUCT -->
  <section class="section featured-product">
    <div class="featured-product-inner">
      <div class="featured-text">
        <span class="label">New Arrival</span>
        <h2>New Citrus Energy Refreshers just dropped</h2>
        <p>Introducing a new kind of energy. Now you can enjoy the Refreshers you love with extra caffeine from nature and a B-vitamin boost.</p>
        <a href="menu.html" class="btn-green">Give them a try</a>
      </div>
      <div class="featured-visual">🍋</div>
    </div>
  </section>

  <!-- AFTERNOON PROMO & AI RECOMMENDATION GRID -->
  <section class="section">
    <div class="section-inner">
      <div class="promo-grid">
        <!-- Afternoon promo -->
        <div class="promo-card">
          <div class="promo-card-img" style="background: linear-gradient(135deg, #FFE8C0 0%, #FFD08A 100%);">☀️</div>
          <div class="promo-card-body">
            <h3>Your afternoon reset</h3>
            <p>When 2 p.m. hits and you need a little boost, we've got you covered — with tasty drinks, snacks and sweet treats to keep the good vibes going.</p>
            <a href="menu.html" class="btn-green">Explore our afternoon menu</a>
          </div>
        </div>
        <!-- Nondairy -->
        <div class="promo-card">
          <div class="promo-card-img" style="background: linear-gradient(135deg, #E8F5F0 0%, #B8E4D0 100%);">🌿</div>
          <div class="promo-card-body">
            <h3>Nondairy, No extra</h3>
            <p>Enjoy your beverage with your choice of nondairy milk — like oat, almond, coconut or soy — for no additional charge.</p>
            <a href="menu.html" class="btn-green">Start an order</a>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- AI RECOMMENDATION -->
  <section class="ai-section">
    <div class="ai-inner">
      <div class="ai-badge">✨ AI-Powered</div>
      <h2>Inspire your next order with ChatGPT</h2>
      <p>Discover drinks that fit your mood, goals and preferences in just a few conversational prompts.</p>
      <a href="#" class="btn-cream">Learn more</a>
    </div>
  </section>

  <!-- SEASONAL HIGHLIGHTS -->
  <section class="section seasonal-section">
    <div class="section-inner">
      <h2 style="font-family:'Playfair Display',serif; font-size:clamp(26px,3.5vw,40px); font-weight:800; color:var(--forest); margin-bottom:36px; text-align:center;">What's fresh this season</h2>
      <div class="seasonal-inner">
        <div class="seasonal-card">
          <div class="seasonal-card-img" style="background: linear-gradient(135deg, #FFF3E0 0%, #FFE082 100%);">🥭</div>
          <div class="seasonal-card-body">
            <h3>A new fruity twist is here</h3>
            <p>Introducing vibrant Iced Mango Cream Matcha and rich Iced Mango Cream Chai. Topped with velvety mango cream cold foam for a delicious pop of sweetness, sip after sip.</p>
            <a href="menu.html" class="btn-green">Order now</a>
          </div>
