  <script>
    const carouselState = {};

    function getTrackInfo(id) {
      const track = document.getElementById(id + '-track');
      if (!track) return null;
      const items = track.children;
      const itemCount = items.length;
      if (itemCount === 0) return null;
      const gap = 20;
      const containerWidth = track.parentElement.offsetWidth;
      const itemWidth = items[0].offsetWidth + gap;
      const visibleCount = Math.max(1, Math.floor(containerWidth / itemWidth));
      return { track, itemCount, itemWidth, visibleCount, gap };
    }

    function slide(id, dir) {
      if (!carouselState[id]) carouselState[id] = 0;
      const info = getTrackInfo(id);
      if (!info) return;
      const maxIndex = Math.max(0, info.itemCount - info.visibleCount);
      carouselState[id] = Math.max(0, Math.min(maxIndex, carouselState[id] + dir));
      info.track.style.transform = `translateX(-${carouselState[id] * info.itemWidth}px)`;
      // Update featured buttons
      const prevBtn = document.getElementById(id + '-prev');
      const nextBtn = document.getElementById(id + '-next');
      if (prevBtn) prevBtn.disabled = carouselState[id] <= 0;
      if (nextBtn) nextBtn.disabled = carouselState[id] >= maxIndex;
    }

    function switchCategory(name, btn) {
      document.querySelectorAll('.category-panel').forEach(p => p.classList.remove('active'));
      document.querySelectorAll('.cat-tab').forEach(b => b.classList.remove('active'));
      document.getElementById('cat-' + name).classList.add('active');
      btn.classList.add('active');
    }

    function toggleFaq(btn) {
      const item = btn.closest('.faq-item');
      item.classList.toggle('open');
    }
