      border: 1px solid rgba(0,0,0,0.08);
    }
    .store-actions { display: flex; gap: 8px; margin-top: 12px; }
    .store-action-btn {
      padding: 7px 14px;
      border-radius: 999px;
      border: 1px solid rgba(0,130,74,0.25);
      background: var(--white);
      color: var(--green);
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      font-family: 'DM Sans', sans-serif;
      transition: background 0.2s, color 0.2s;
    }
    .store-action-btn:hover { background: var(--green); color: white; }
    .store-action-btn.primary { background: var(--green); color: white; border-color: var(--green); }
    .store-action-btn.primary:hover { background: var(--green-dark); }

    /* MAP PANEL */
    .map-panel {
      position: relative;
      background: #e8f0eb;
      overflow: hidden;
    }
    .map-canvas {
      width: 100%;
      height: 100%;
      min-height: 500px;
      position: relative;
      background: linear-gradient(135deg, #e8f4ea 0%, #d5ebda 40%, #c2e3ca 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    /* Map grid lines (decorative) */
    .map-canvas::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image:
        linear-gradient(rgba(0,130,74,0.08) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0,130,74,0.08) 1px, transparent 1px);
      background-size: 48px 48px;
    }

    /* Map roads (decorative) */
    .map-roads {
      position: absolute;
      inset: 0;
      overflow: hidden;
    }
    .map-road {
      position: absolute;
      background: rgba(255,255,255,0.7);
      border-radius: 2px;
    }

    /* Store pins */
    .map-pins { position: absolute; inset: 0; }
    .map-pin {
      position: absolute;
      transform: translate(-50%, -100%);
      cursor: pointer;
      transition: transform 0.2s;
      z-index: 10;
    }
    .map-pin:hover { transform: translate(-50%, -100%) scale(1.2); z-index: 20; }
    .map-pin.selected { transform: translate(-50%, -100%) scale(1.2); z-index: 20; }
    .pin-bubble {
      background: var(--green);
      color: white;
      border-radius: 50% 50% 50% 0;
      width: 36px; height: 36px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      box-shadow: 0 4px 16px rgba(0,130,74,0.4);
      transform: rotate(-45deg);
      border: 2px solid white;
    }
    .pin-bubble-inner { transform: rotate(45deg); }
    .map-pin.selected .pin-bubble { background: var(--forest); }
    .pin-label {
      position: absolute;
      bottom: calc(100% + 4px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      color: var(--text);
      font-size: 11px;
      font-weight: 700;
      padding: 4px 8px;
      border-radius: 6px;
      white-space: nowrap;
      box-shadow: var(--shadow);
      display: none;
    }
    .map-pin:hover .pin-label, .map-pin.selected .pin-label { display: block; }

    /* MAP OVERLAY CARD */
    .map-store-card {
      position: absolute;
      bottom: 20px;
      left: 20px;
      right: 20px;
      background: var(--white);
      border-radius: 16px;
      padding: 20px;
      box-shadow: var(--shadow-lg);
      display: none;
      z-index: 30;
    }
    .map-store-card.visible { display: block; }
    .map-store-card h3 { font-size: 16px; font-weight: 700; color: var(--forest); margin-bottom: 4px; }
    .map-store-card p { font-size: 13px; color: var(--text-mid); margin-bottom: 12px; }
    .map-store-card .btn-green { display: inline-block; background: var(--green); color: var(--white); padding: 8px 20px; border-radius: 999px; font-size: 13px; font-weight: 600; text-decoration: none; border: none; cursor: pointer; }
    .map-close-btn { position: absolute; top: 12px; right: 12px; background: none; border: none; font-size: 18px; cursor: pointer; color: var(--text-light); }

    /* MAP CONTROLS */
    .map-zoom-controls {
      position: absolute;
      top: 16px;
      right: 16px;
      display: flex;
      flex-direction: column;
      gap: 4px;
      z-index: 20;
    }
    .map-zoom-btn {
      width: 36px; height: 36px;
      background: var(--white);
      border: 1px solid rgba(0,0,0,0.12);
      border-radius: 8px;
      font-size: 18px;
      font-weight: 700;
      cursor: pointer;
      color: var(--text);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow);
      transition: background 0.2s;
    }
    .map-zoom-btn:hover { background: var(--cream-light); }
    .map-location-btn {
      width: 36px; height: 36px;
      background: var(--white);
      border: 1px solid rgba(0,0,0,0.12);
      border-radius: 8px;
      font-size: 16px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow);
      margin-top: 8px;
      transition: background 0.2s;
    }
    .map-location-btn:hover { background: var(--cream-light); }

    /* NO RESULTS */
    .no-results {
      padding: 48px 24px;
      text-align: center;
      color: var(--text-light);
      display: none;
    }
    .no-results .icon { font-size: 48px; margin-bottom: 12px; }
    .no-results h3 { font-size: 17px; font-weight: 700; color: var(--text-mid); margin-bottom: 6px; }

    /* FOOTER */
    footer { background: var(--forest); color: rgba(255,255,255,0.85); padding: 64px 24px 32px; }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 48px; margin-bottom: 48px; }
    .footer-col h4 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--cream); margin-bottom: 16px; }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 10px; }
    .footer-col ul li a { text-decoration: none; color: rgba(255,255,255,0.65); font-size: 14px; transition: color 0.2s; }
    .footer-col ul li a:hover { color: var(--cream); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,0.12); padding-top: 28px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px; }
    .footer-logo { display: flex; align-items: center; gap: 10px; }
    .footer-logo-mark { width: 36px; height: 36px; background: var(--green); border-radius: 50%; display: flex; align-items: center; justify-content: center; }
    .footer-logo-text { font-family: 'Playfair Display', serif; font-size: 18px; font-weight: 700; color: var(--cream); }
    .footer-copy { font-size: 13px; color: rgba(255,255,255,0.4); }

    @media (max-width: 1024px) {
      .locator-body { grid-template-columns: 340px 1fr; }
    }
    @media (max-width: 800px) {
      .locator-body { grid-template-columns: 1fr; }
      .map-panel { min-height: 380px; }
      .results-panel { max-height: 480px; border-right: none; border-top: 1px solid rgba(0,0,0,0.08); }
    }
    @media (max-width: 768px) {
      nav { display: none; }
      .search-controls-inner { gap: 8px; }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
    }
  </style>
</head>
<body>

