      </div>
    </div>

    <!-- LOCATOR BODY -->
    <div class="locator-body">

      <!-- MAP -->
      <div class="map-panel">
        <div class="map-canvas" id="map-canvas">
          <!-- Decorative roads -->
          <div class="map-roads">
            <div class="map-road" style="width:100%;height:4px;top:35%;left:0"></div>
