            <div class="map-road" style="width:100%;height:2px;top:20%;left:0;opacity:0.5"></div>
          </div>

          <!-- Store Pins -->
          <div class="map-pins">
            <div class="map-pin" style="left:30%;top:38%" id="pin-1" onclick="selectStore(1)">
              <div class="pin-label">Downtown — 0.3 mi</div>
              <div class="pin-bubble"><span class="pin-bubble-inner">☕</span></div>
            </div>
            <div class="map-pin" style="left:57%;top:60%" id="pin-2" onclick="selectStore(2)">
              <div class="pin-label">Midtown — 0.8 mi</div>
              <div class="pin-bubble"><span class="pin-bubble-inner">☕</span></div>
            </div>
            <div class="map-pin" style="left:22%;top:22%" id="pin-3" onclick="selectStore(3)">
              <div class="pin-label">Northside — 1.2 mi</div>
              <div class="pin-bubble"><span class="pin-bubble-inner">☕</span></div>
            </div>
            <div class="map-pin" style="left:75%;top:42%" id="pin-4" onclick="selectStore(4)">
              <div class="pin-label">Eastside — 1.7 mi</div>
              <div class="pin-bubble"><span class="pin-bubble-inner">☕</span></div>
            </div>
            <div class="map-pin" style="left:45%;top:78%" id="pin-5" onclick="selectStore(5)">
              <div class="pin-label">South Loop — 2.1 mi</div>
              <div class="pin-bubble"><span class="pin-bubble-inner">☕</span></div>
            </div>
          </div>

          <!-- User location dot -->
          <div style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:5">
            <div style="width:16px;height:16px;background:var(--green);border-radius:50%;border:3px solid white;box-shadow:0 0 0 6px rgba(0,130,74,0.2)"></div>
          </div>

          <!-- Zoom controls -->
          <div class="map-zoom-controls">
            <button class="map-zoom-btn" title="Zoom in">+</button>
            <button class="map-zoom-btn" title="Zoom out">−</button>
            <button class="map-location-btn" title="Use my location">📍</button>
          </div>

          <!-- Map attribution -->
          <div style="position:absolute;bottom:8px;right:8px;font-size:10px;color:rgba(0,0,0,0.4);background:rgba(255,255,255,0.7);padding:2px 6px;border-radius:4px">Map placeholder © GreenBean</div>

        </div>

        <!-- Map store overlay -->
        <div class="map-store-card" id="map-store-overlay">
          <button class="map-close-btn" onclick="closeMapOverlay()">✕</button>
