  <script>
    // Store data
    const allStores = [
      {
        id: 1,
        name: 'GreenBean Downtown',
        address: '123 Main St, Suite 101',
        city: 'Chicago, IL 60601',
        distance: '0.3 mi',
        isOpen: true,
        hours: 'Open until 9:00 PM',
        features: ['Drive-Thru', 'Mobile Ordering', 'Free Wi-Fi'],
        pickup: true,
        delivery: true,
      },
      {
        id: 2,
        name: 'GreenBean Midtown',
        address: '450 Michigan Ave',
        city: 'Chicago, IL 60611',
        distance: '0.8 mi',
        isOpen: true,
        hours: 'Open until 10:00 PM',
        features: ['Mobile Ordering', 'Free Wi-Fi', 'Outdoor Seating'],
        pickup: true,
        delivery: false,
      },
      {
        id: 3,
        name: 'GreenBean Northside',
        address: '892 Clark Street',
        city: 'Chicago, IL 60614',
        distance: '1.2 mi',
        isOpen: true,
        hours: 'Open until 8:00 PM',
        features: ['Mobile Ordering', 'Free Wi-Fi'],
        pickup: true,
        delivery: true,
      },
      {
        id: 4,
        name: 'GreenBean Eastside',
        address: '2101 S. Lake Shore Drive',
        city: 'Chicago, IL 60616',
        distance: '1.7 mi',
        isOpen: false,
        hours: 'Opens tomorrow at 6:00 AM',
        features: ['Drive-Thru', 'Mobile Ordering', 'Open 24 hours', 'Outdoor Seating'],
        pickup: true,
        delivery: true,
      },
      {
        id: 5,
        name: 'GreenBean South Loop',
        address: '55 E. Cermak Road',
        city: 'Chicago, IL 60605',
        distance: '2.1 mi',
        isOpen: true,
        hours: 'Open until 7:00 PM',
        features: ['Mobile Ordering'],
        pickup: true,
        delivery: false,
      },
    ];

    let currentOrderType = 'pickup';
    let selectedStoreId = null;
    let activeFilters = new Set();
    let searchQuery = '';
    let displayedStores = [...allStores];

    const suggestions = [
      { icon: '📍', text: 'Current Location', sub: 'Use my GPS location' },
      { icon: '🏙️', text: 'Chicago, IL', sub: 'Cook County, Illinois' },
      { icon: '🏙️', text: 'New York, NY', sub: 'Manhattan, New York' },
      { icon: '🏙️', text: 'Los Angeles, CA', sub: 'Los Angeles County, California' },
      { icon: '🏙️', text: 'Seattle, WA', sub: 'King County, Washington' },
    ];

    function renderStores(stores) {
      const list = document.getElementById('results-list');
      const noResults = document.getElementById('no-results');
      document.getElementById('results-count').textContent = `Showing ${stores.length} location${stores.length !== 1 ? 's' : ''}`;

      if (stores.length === 0) {
        list.innerHTML = '';
        noResults.style.display = 'block';
        return;
      }
      noResults.style.display = 'none';

      list.innerHTML = stores.map(store => `
        <div class="store-card ${store.id === selectedStoreId ? 'selected' : ''}" id="card-${store.id}" onclick="selectStore(${store.id})">
          <div class="store-card-top">
            <div class="store-name">☕ ${store.name}</div>
            <div class="store-distance">${store.distance}</div>
          </div>
          <div class="store-address">${store.address}<br>${store.city}</div>
          <div class="store-hours">
            <span class="${store.isOpen ? 'open' : ''}" style="${!store.isOpen ? 'color:var(--text-light)' : ''}">${store.isOpen ? '● Open' : '● Closed'}</span>
            <span class="hours"> · ${store.hours}</span>
          </div>
          <div class="store-features">
            ${store.features.map(f => `<span class="store-feature-tag">${getFeatureIcon(f)} ${f}</span>`).join('')}
          </div>
          <div class="store-actions">
            <button class="store-action-btn primary" onclick="event.stopPropagation()">Order here</button>
            <button class="store-action-btn" onclick="event.stopPropagation()">Directions</button>
            <button class="store-action-btn" onclick="event.stopPropagation()">Details</button>
          </div>
        </div>
      `).join('');
    }

    function getFeatureIcon(feature) {
      const icons = { 'Drive-Thru': '🚗', 'Mobile Ordering': '📱', 'Free Wi-Fi': '📶', 'Outdoor Seating': '☀️', 'Open 24 hours': '🌙' };
      return icons[feature] || '✓';
    }

    function selectStore(id) {
      selectedStoreId = id;
      const store = allStores.find(s => s.id === id);

      // Update store list
      document.querySelectorAll('.store-card').forEach(c => c.classList.remove('selected'));
      const card = document.getElementById('card-' + id);
      if (card) { card.classList.add('selected'); card.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }

      // Update map pins
      document.querySelectorAll('.map-pin').forEach(p => p.classList.remove('selected'));
      const pin = document.getElementById('pin-' + id);
      if (pin) pin.classList.add('selected');

      // Show map overlay
      const overlay = document.getElementById('map-store-overlay');
      document.getElementById('overlay-name').textContent = store.name;
      document.getElementById('overlay-detail').textContent = store.address + ', ' + store.city + ' · ' + store.distance;
      overlay.classList.add('visible');
    }

    function closeMapOverlay() {
      document.getElementById('map-store-overlay').classList.remove('visible');
      selectedStoreId = null;
      document.querySelectorAll('.store-card').forEach(c => c.classList.remove('selected'));
      document.querySelectorAll('.map-pin').forEach(p => p.classList.remove('selected'));
    }

    function setOrderType(type) {
      currentOrderType = type;
      document.getElementById('pickup-btn').classList.toggle('active', type === 'pickup');
      document.getElementById('delivery-btn').classList.toggle('active', type === 'delivery');

      // Filter by order type
      displayedStores = allStores.filter(s => type === 'pickup' ? s.pickup : s.delivery);
      applySearchAndFilters();
    }

    function handleSearchInput(val) {
      searchQuery = val.trim();
      const sugg = document.getElementById('suggestions-list');

      if (searchQuery.length > 0) {
        const filtered = suggestions.filter(s =>
          s.text.toLowerCase().includes(searchQuery.toLowerCase()) ||
          s.sub.toLowerCase().includes(searchQuery.toLowerCase())
        );
        if (filtered.length > 0) {
          sugg.innerHTML = filtered.map(s => `
            <div class="suggestion-item" onclick="selectSuggestion('${s.text}')">
              <span class="sug-icon">${s.icon}</span>
              <div><div>${s.text}</div><div class="sug-sub">${s.sub}</div></div>
            </div>
          `).join('');
          sugg.classList.add('visible');
        } else {
          sugg.classList.remove('visible');
        }
      } else {
        sugg.classList.remove('visible');
      }
      applySearchAndFilters();
    }

    function showSuggestions() {
      if (document.getElementById('location-input').value.length > 0) {
        handleSearchInput(document.getElementById('location-input').value);
      }
    }

    function selectSuggestion(text) {
      document.getElementById('location-input').value = text;
      document.getElementById('suggestions-list').classList.remove('visible');
      searchQuery = text;
      document.getElementById('results-heading').textContent = 'Stores near ' + text;
      applySearchAndFilters();
    }

    function toggleFilterPanel() {
      document.getElementById('filter-panel').classList.toggle('visible');
    }

    function updateFilters() {
      const checked = document.querySelectorAll('.filter-panel input[type="checkbox"]:checked');
      activeFilters = new Set([...checked].map(c => c.value));
      const badge = document.getElementById('filter-badge');
      const btn = document.getElementById('filter-btn');
      badge.textContent = activeFilters.size;
      if (activeFilters.size > 0) {
        badge.style.display = 'inline';
        btn.classList.add('has-filters');
      } else {
        badge.style.display = 'none';
        btn.classList.remove('has-filters');
      }
    }

    function clearFilters() {
      document.querySelectorAll('.filter-panel input[type="checkbox"]').forEach(c => c.checked = false);
      activeFilters.clear();
      document.getElementById('filter-badge').style.display = 'none';
      document.getElementById('filter-btn').classList.remove('has-filters');
      applySearchAndFilters();
    }

    function applyFilters() {
      updateFilters();
      document.getElementById('filter-panel').classList.remove('visible');
      applySearchAndFilters();
    }

    function applySearchAndFilters() {
      let stores = allStores.filter(s =>
        currentOrderType === 'pickup' ? s.pickup : s.delivery
      );

      if (activeFilters.has('open-now')) stores = stores.filter(s => s.isOpen);
      if (activeFilters.has('drive-thru')) stores = stores.filter(s => s.features.includes('Drive-Thru'));
      if (activeFilters.has('mobile-order')) stores = stores.filter(s => s.features.includes('Mobile Ordering'));
      if (activeFilters.has('wifi')) stores = stores.filter(s => s.features.includes('Free Wi-Fi'));
      if (activeFilters.has('outdoor')) stores = stores.filter(s => s.features.includes('Outdoor Seating'));
      if (activeFilters.has('open-24h')) stores = stores.filter(s => s.features.includes('Open 24 hours'));

      renderStores(stores);
    }

    // Close dropdowns on outside click
    document.addEventListener('click', e => {
      if (!e.target.closest('.search-field')) {
        document.getElementById('suggestions-list').classList.remove('visible');
      }
      if (!e.target.closest('#filter-btn') && !e.target.closest('#filter-panel')) {
        document.getElementById('filter-panel').classList.remove('visible');
      }
    });

    // Initial render
    renderStores(allStores);
  </script>
</body>
</html>
